import{_ as i,o as a,c as e,ag as o}from"./chunks/framework.DWOJQht4.js";const b=JSON.parse('{"title":"平台系统集成测试方案","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platform-integration-test-plan.md","filePath":"guide/platform-integration-test-plan.md","lastUpdated":1792636228000}'),t={name:"guide/platform-integration-test-plan.md"};function r(d,l,h,c,n,s){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="平台系统集成测试方案" tabindex="-1">平台系统集成测试方案 <a class="header-anchor" href="#平台系统集成测试方案" aria-label="Permalink to &quot;平台系统集成测试方案&quot;">​</a></h1><h2 id="_1-文档目标" tabindex="-1">1. 文档目标 <a class="header-anchor" href="#_1-文档目标" aria-label="Permalink to &quot;1. 文档目标&quot;">​</a></h2><p>本文档用于定义 CloudCTF 平台的系统集成测试范围、执行流程、验收标准与后续 CI/CD 自动化接入方向。</p><p>目标是保证在代码提交到 CI/CD 后，可以自动启动完整平台，并验证以下关键链路：</p><ol><li>管理端基础配置与比赛编排流程可用。</li><li>内置资源同步链路可用。</li><li>模板编译链路可用。</li><li>题目与资源绑定链路可用。</li><li>比赛开始前访问控制正确。</li><li>比赛开始后答题与交卷链路可用。</li><li>漏洞复现环境启动链路可用。</li></ol><h2 id="_2-测试范围" tabindex="-1">2. 测试范围 <a class="header-anchor" href="#_2-测试范围" aria-label="Permalink to &quot;2. 测试范围&quot;">​</a></h2><p>本次系统测试覆盖以下模块：</p><ol><li>管理后台认证与业务编排。</li><li>用户、队伍、比赛、题目、理论试卷管理。</li><li>资源仓库同步。</li><li>模板编译与模板状态更新。</li><li>CTF 练习场与比赛题目绑定。</li><li>比赛时间控制与权限控制。</li><li>Flag 提交、理论答题与试卷提交。</li><li>漏洞环境启动与容器运行状态检查。</li></ol><p>本次测试暂不覆盖：</p><ol><li>历史数据迁移校验。</li><li>大规模性能压测。</li><li>多节点高可用部署。</li><li>邮件、短信、第三方告警集成。</li></ol><h2 id="_3-测试环境要求" tabindex="-1">3. 测试环境要求 <a class="header-anchor" href="#_3-测试环境要求" aria-label="Permalink to &quot;3. 测试环境要求&quot;">​</a></h2><p>建议在 CI 集成环境中准备一套独立测试环境，要求如下：</p><ol><li>可启动前端、后端、数据库。</li><li>可访问 Docker 或等价容器运行时。</li><li>支持模板编译、容器拉起、容器状态查询。</li><li>测试环境网络允许访问内置资源仓库或内置同步源。</li><li>每次测试使用独立数据库或临时数据库，避免测试互相污染。</li></ol><p>建议环境变量至少包括：</p><ol><li>管理员初始账号信息。</li><li>数据库连接信息。</li><li>Docker / 虚拟化主机连接信息。</li><li>测试用资源仓库配置。</li><li>平台基础访问地址。</li></ol><h2 id="_4-测试数据设计" tabindex="-1">4. 测试数据设计 <a class="header-anchor" href="#_4-测试数据设计" aria-label="Permalink to &quot;4. 测试数据设计&quot;">​</a></h2><p>建议固定使用以下测试对象，保证脚本可重复执行：</p><ol><li>管理员账号：<code>admin</code></li><li>队伍：<code>ci-team-01</code></li><li>普通用户：<code>ci-player-01</code></li><li>CTF 比赛：<code>CI CTF Competition</code></li><li>理论赛比赛：<code>CI Theory Competition</code></li><li>CTF 题目模板资源：<code>F12</code></li><li>漏洞模板资源：<code>tomcat</code></li><li>理论试卷：<code>CI Theory Paper</code></li></ol><p>建议所有测试对象命名加 <code>ci-</code> 前缀，便于隔离与清理。</p><h2 id="_5-测试前置条件" tabindex="-1">5. 测试前置条件 <a class="header-anchor" href="#_5-测试前置条件" aria-label="Permalink to &quot;5. 测试前置条件&quot;">​</a></h2><p>执行前需要确认：</p><ol><li>平台服务已正常启动。</li><li>数据库已完成 schema 初始化。</li><li>管理员账号可登录。</li><li>默认虚拟化主机配置可用。</li><li>内置资源源中存在 CTFDB 与 vulhub 可同步内容。</li><li>F12 与 tomcat 资源可被成功同步并参与编译。</li></ol><h2 id="_6-核心测试流程" tabindex="-1">6. 核心测试流程 <a class="header-anchor" href="#_6-核心测试流程" aria-label="Permalink to &quot;6. 核心测试流程&quot;">​</a></h2><h3 id="_6-1-管理端基础编排" tabindex="-1">6.1 管理端基础编排 <a class="header-anchor" href="#_6-1-管理端基础编排" aria-label="Permalink to &quot;6.1 管理端基础编排&quot;">​</a></h3><h4 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证管理员可以完成完整的比赛与用户初始化流程。</p><h4 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>登录管理系统。</li><li>创建测试队伍 <code>ci-team-01</code>。</li><li>创建测试用户 <code>ci-player-01</code>。</li><li>将测试用户加入测试队伍。</li><li>创建一个 CTF 比赛 <code>CI CTF Competition</code>。</li><li>创建一个理论赛比赛 <code>CI Theory Competition</code>。</li><li>为 CTF 比赛添加至少一道比赛题目。</li><li>为理论赛比赛创建并绑定一套试卷，或绑定已有理论题。</li></ol><h4 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>所有创建接口返回成功。</li><li>队伍、用户、比赛、题目、试卷均可在管理端列表查询到。</li><li>比赛与题目、比赛与试卷的绑定关系正确。</li></ol><h3 id="_6-2-同步内置资源" tabindex="-1">6.2 同步内置资源 <a class="header-anchor" href="#_6-2-同步内置资源" aria-label="Permalink to &quot;6.2 同步内置资源&quot;">​</a></h3><h4 id="目标-1" tabindex="-1">目标 <a class="header-anchor" href="#目标-1" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证 CTFDB 与 vulhub 内置资源同步能力正常。</p><h4 id="步骤-1" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>在管理端触发 CTFDB 资源同步。</li><li>检查同步任务状态与同步日志。</li><li>确认至少同步出目标资源 <code>F12</code>。</li><li>在管理端触发 vulhub 资源同步。</li><li>检查同步任务状态与同步日志。</li><li>确认至少同步出目标资源 <code>tomcat</code>。</li></ol><h4 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>同步接口返回成功。</li><li>同步日志状态为成功、完成或等价成功状态。</li><li>模板列表中可以查询到 <code>F12</code> 与 <code>tomcat</code>。</li><li>模板状态、路径、来源仓库等关键字段完整。</li></ol><h3 id="_6-3-编译-f12-与-tomcat-资源" tabindex="-1">6.3 编译 F12 与 tomcat 资源 <a class="header-anchor" href="#_6-3-编译-f12-与-tomcat-资源" aria-label="Permalink to &quot;6.3 编译 F12 与 tomcat 资源&quot;">​</a></h3><h4 id="目标-2" tabindex="-1">目标 <a class="header-anchor" href="#目标-2" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证模板编译链路正常。</p><h4 id="步骤-2" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-2" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>对 <code>F12</code> 模板触发编译。</li><li>轮询构建任务状态与构建日志。</li><li>验证 <code>F12</code> 模板最终状态为 <code>completed</code>、<code>ready</code> 或平台定义的成功状态。</li><li>对 <code>tomcat</code> 模板触发编译。</li><li>轮询构建任务状态与构建日志。</li><li>验证 <code>tomcat</code> 模板最终状态为 <code>completed</code>、<code>ready</code> 或平台定义的成功状态。</li></ol><h4 id="验收标准-2" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-2" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>两个模板均能进入构建流程。</li><li>构建日志中无致命错误。</li><li>模板最终状态为成功。</li><li>模板端口、服务信息等运行时元数据被正确生成。</li></ol><h3 id="_6-4-将-f12-资源添加到练习场和比赛题目" tabindex="-1">6.4 将 F12 资源添加到练习场和比赛题目 <a class="header-anchor" href="#_6-4-将-f12-资源添加到练习场和比赛题目" aria-label="Permalink to &quot;6.4 将 F12 资源添加到练习场和比赛题目&quot;">​</a></h3><h4 id="目标-3" tabindex="-1">目标 <a class="header-anchor" href="#目标-3" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证模板与题目绑定逻辑可用。</p><h4 id="步骤-3" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-3" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>在练习场创建一个使用 <code>F12</code> 模板的动态题目。</li><li>在 CTF 比赛中创建或更新一道比赛题目，并绑定 <code>F12</code> 模板。</li><li>确认题目启用了动态容器或关联模板字段。</li><li>使用管理端查看题目详情，确认模板绑定关系。</li></ol><h4 id="验收标准-3" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-3" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>练习场动态题目创建成功。</li><li>比赛题目绑定模板成功。</li><li>题目详情中能看到正确的模板 ID、主机 ID、动态标记等字段。</li></ol><h3 id="_6-5-比赛未开始前的访问控制测试" tabindex="-1">6.5 比赛未开始前的访问控制测试 <a class="header-anchor" href="#_6-5-比赛未开始前的访问控制测试" aria-label="Permalink to &quot;6.5 比赛未开始前的访问控制测试&quot;">​</a></h3><h4 id="目标-4" tabindex="-1">目标 <a class="header-anchor" href="#目标-4" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证比赛开始前用户不能越权获取或提交比赛内容。</p><h4 id="步骤-4" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-4" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>使用测试用户登录前台。</li><li>访问 CTF 比赛详情页或题目列表。</li><li>尝试获取比赛题目详情。</li><li>尝试提交 Flag。</li><li>访问理论赛比赛详情页或试卷页面。</li><li>尝试获取试卷内容。</li><li>尝试提交理论试卷。</li></ol><h4 id="验收标准-4" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-4" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>未开始比赛的题目访问应被拒绝，或返回空列表，或返回未开始状态。</li><li>未开始比赛的 Flag 提交应失败。</li><li>未开始比赛的试卷获取应失败，或返回未开始状态。</li><li>未开始比赛的试卷提交应失败。</li></ol><h3 id="_6-6-开始比赛" tabindex="-1">6.6 开始比赛 <a class="header-anchor" href="#_6-6-开始比赛" aria-label="Permalink to &quot;6.6 开始比赛&quot;">​</a></h3><h4 id="目标-5" tabindex="-1">目标 <a class="header-anchor" href="#目标-5" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证比赛状态流转正常。</p><h4 id="步骤-5" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-5" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>将 CTF 比赛状态切换为开始，或将比赛时间设置到当前时刻。</li><li>将理论赛比赛状态切换为开始，或将比赛时间设置到当前时刻。</li><li>重新获取比赛详情。</li><li>确认前台用户可见比赛状态已更新。</li></ol><h4 id="验收标准-5" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-5" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>比赛状态更新成功。</li><li>前后台查询结果一致。</li><li>平台将比赛识别为进行中状态。</li></ol><h3 id="_6-7-比赛开始后的答题与交卷测试" tabindex="-1">6.7 比赛开始后的答题与交卷测试 <a class="header-anchor" href="#_6-7-比赛开始后的答题与交卷测试" aria-label="Permalink to &quot;6.7 比赛开始后的答题与交卷测试&quot;">​</a></h3><h4 id="目标-6" tabindex="-1">目标 <a class="header-anchor" href="#目标-6" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证比赛开始后核心业务链路正常。</p><h4 id="步骤-6" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-6" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>使用测试用户访问 CTF 比赛题目列表。</li><li>获取比赛题目详情。</li><li>提交一次错误 Flag，验证失败路径。</li><li>提交一次正确 Flag，验证成功路径。</li><li>验证积分、解题状态、提交记录更新。</li><li>使用测试用户访问理论赛试卷。</li><li>提交理论试卷答案。</li><li>验证试卷提交记录、得分、状态更新。</li></ol><h4 id="验收标准-6" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-6" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>比赛开始后题目可正常获取。</li><li>错误 Flag 返回失败。</li><li>正确 Flag 返回成功。</li><li>提交记录、解题状态、排行榜或积分状态正确更新。</li><li>理论试卷可正常获取。</li><li>理论试卷可正常提交。</li><li>提交后系统生成提交记录与评分结果，或进入待评分状态。</li></ol><h3 id="_6-8-漏洞复现环境启动测试" tabindex="-1">6.8 漏洞复现环境启动测试 <a class="header-anchor" href="#_6-8-漏洞复现环境启动测试" aria-label="Permalink to &quot;6.8 漏洞复现环境启动测试&quot;">​</a></h3><h4 id="目标-7" tabindex="-1">目标 <a class="header-anchor" href="#目标-7" aria-label="Permalink to &quot;目标&quot;">​</a></h4><p>验证漏洞环境可以基于模板成功启动。</p><h4 id="步骤-7" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-7" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ol><li>选择基于 <code>tomcat</code> 模板的漏洞环境或动态容器资源。</li><li>触发环境启动。</li><li>轮询容器组状态。</li><li>校验容器组状态从 <code>creating</code> 进入 <code>running</code>。</li><li>获取容器端口映射、访问地址、容器 ID 等运行信息。</li><li>对暴露端口执行一次基础连通性检查。</li></ol><h4 id="验收标准-7" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-7" aria-label="Permalink to &quot;验收标准&quot;">​</a></h4><ol><li>启动接口返回成功。</li><li>容器组成功创建。</li><li>容器最终状态为运行中。</li><li>运行时访问地址和端口信息完整。</li><li>至少一个业务端口可连接。</li></ol><h2 id="_7-结果判定" tabindex="-1">7. 结果判定 <a class="header-anchor" href="#_7-结果判定" aria-label="Permalink to &quot;7. 结果判定&quot;">​</a></h2><p>本轮系统集成测试通过的最低标准如下：</p><ol><li>8 个测试阶段全部执行完成。</li><li>不允许出现平台启动失败、资源同步失败、模板编译失败、比赛状态错误、环境启动失败。</li><li>比赛未开始前必须阻止答题和交卷。</li><li>比赛开始后必须允许答题和交卷。</li><li>F12 与 tomcat 两个目标资源必须完成同步和编译。</li></ol><p>若任意关键步骤失败，应视为本轮集成测试失败。</p><h2 id="_8-建议的自动化拆分" tabindex="-1">8. 建议的自动化拆分 <a class="header-anchor" href="#_8-建议的自动化拆分" aria-label="Permalink to &quot;8. 建议的自动化拆分&quot;">​</a></h2><p>建议后续将自动化拆成以下测试套件：</p><ol><li><code>suite_admin_setup</code></li><li><code>suite_resource_sync</code></li><li><code>suite_template_build</code></li><li><code>suite_competition_access_control</code></li><li><code>suite_competition_submission</code></li><li><code>suite_runtime_environment</code></li></ol><p>这样可以在 CI 中实现：</p><ol><li>失败快速定位。</li><li>支持并行执行。</li><li>支持只重跑失败套件。</li></ol><h2 id="_9-ci-cd-接入建议" tabindex="-1">9. CI/CD 接入建议 <a class="header-anchor" href="#_9-ci-cd-接入建议" aria-label="Permalink to &quot;9. CI/CD 接入建议&quot;">​</a></h2><p>后续接入 CI/CD 时建议采用以下流程：</p><ol><li>启动数据库与平台服务。</li><li>等待健康检查通过。</li><li>注入测试管理员账号与测试环境配置。</li><li>执行系统集成测试脚本。</li><li>收集测试日志、接口响应、构建日志、容器日志。</li><li>失败时上传产物供排查。</li><li>成功后销毁测试环境。</li></ol><p>建议至少保存以下测试产物：</p><ol><li>平台后端日志。</li><li>资源同步日志。</li><li>模板编译日志。</li><li>测试请求响应日志。</li><li>容器组状态快照。</li></ol><h2 id="_10-后续落地建议" tabindex="-1">10. 后续落地建议 <a class="header-anchor" href="#_10-后续落地建议" aria-label="Permalink to &quot;10. 后续落地建议&quot;">​</a></h2><p>基于本文档，下一步建议继续产出以下内容：</p><ol><li>一份自动化测试用例清单，细化到接口和断言。</li><li>一套用于 CI 的测试脚本。</li><li>一份 <code>docker compose</code> 或测试环境启动脚本。</li><li>一份 GitHub Actions 或其他 CI 平台的流水线配置。</li></ol><hr><p>文档状态：初稿 用途：系统集成测试设计与 CI/CD 自动化落地基础文档</p>',98)])])}const m=i(t,[["render",r]]);export{b as __pageData,m as default};
